    {
        "name": "Aspergillosis",
        "name_ja": "アスペルギルス症",
        "symptoms": {"respiratory_distress", "nasal_discharge", "lethargy", "anorexia", "weight_loss"},
        "description": "不適切な温度管理に関連する鼻腔・声門の細菌・ウイルス感染症です。",
        "description_ja": "アスペルギルス属真菌による呼吸器の真菌感染症です。",
        "urgency": "high",
        "recommended_tests": ["fungal_culture", "radiographs", "tracheal_wash"],
        "causes": "Fungal infection via spore inhalation, direct inoculation, or mucosal colonization. Immunosuppression, humid environments, poor ventilation, and chronic antibiotic use increase susceptibility.",
        "causes_ja": "Snakeにおけるアスペルギルス症（Snake）の原因: 胞子吸入、直接接種、粘膜コロニー形成による真菌感染。免疫抑制、多湿環境、換気不良、長期抗菌薬使用が感受性を高める。",
        "pathophysiology": "Aspergillosis in Snake Fungal organisms establish infection through spore inhalation, direct inoculation, or mucosal colonization. Hyphae or yeast forms penetrate tissues via enzymatic degradation and mechanical pressure, eliciting a granulomatous inflammatory response. Immunocompromised individuals are particularly susceptible. The infection may remain localized or disseminate hematogenously to distant organs. Chronic infections can lead to fibrosis, tissue remodeling, and progressive organ dysfunction.",
        "pathophysiology_ja": "アスペルギルス症（Snake）はSnakeにおける真菌感染症である。真菌は胞子吸入、直接接種、または粘膜コロニー形成を通じて感染を確立する。菌糸または酵母形態が酵素分解と機械的圧力により組織に侵入し、肉芽腫性炎症反応を惹起する。免疫不全個体は特に感受性が高い。感染は局所にとどまるか、血行性に遠隔臓器へ播種される可能性がある。慢性感染は線維化、組織リモデリング、進行性臓器機能障害を引き起こしうる。",
        "treatment": "Treatment of aspergillosis in snake requires systemic antifungal therapy. Azole antifungals (fluconazole, itraconazole, ketoconazole) or amphotericin B may be used depending on the organism and severity. Treatment duration is typically prolonged (weeks to months) to ensure complete clearance. Topical antifungal agents may be used adjunctively for superficial infections. Environmental decontamination reduces reinfection risk. Monitor hepatic function during prolonged azole therapy.",
        "treatment_ja": "Snakeにおけるアスペルギルス症（Snake）の治療には全身性抗真菌薬療法が必要である。アゾール系抗真菌薬（フルコナゾール、イトラコナゾール、ケトコナゾール）またはアムホテリシンBが菌種と重症度に応じて使用される。治療期間は完全な除菌のため通常長期間（数週間〜数ヶ月）を要する。表在性感染には局所抗真菌剤を併用する。環境消毒により再感染リスクを低減する。長期アゾール療法中は肝機能をモニタリングする。",
        "prevention": "アスペルギルス症（Snake）の予防には適切な環境湿度・温度の維持、良好な換気、過密の回避、定期的な清掃・消毒、罹患個体の隔離、適切な栄養による免疫機能の維持が含まれる。",
        "prevention_ja": "アスペルギルス症（Snake）の予防には適切な環境湿度・温度の維持、良好な換気、過密の回避、定期的な清掃・消毒、罹患個体の隔離、適切な栄養による免疫機能の維持が含まれる。",
        "prognosis": "",
        "prognosis_ja": "アスペルギルス症（Snake）の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"subacute", "chronic"},
        "age_predisposition": {"puppy", "young", "adult", "senior"},
    },
