    {
        "name": "Drowning / Near-Drowning",
        "name_ja": "溺水・溺水未遂",
        "symptoms": {"cyanosis", "lethargy", "respiratory_distress", "unconsciousness"},
        "description": "清掃剤や床材化学物質との接触による化学熱傷。",
        "description_ja": "水容器やケージ内での溺水による酸素欠乏。",
        "urgency": "emergency",
        "recommended_tests": ["clinical_examination", "radiography"],
        "causes": "Oxygen deprivation from near-drowning in water bowls or enclosures.",
        "causes_ja": "Snakeにおける溺水・溺水未遂の原因: 水容器やケージ内での溺水による酸素欠乏。",
        "pathophysiology": "Drowning / Near-Drowning is a traumatic/mechanical condition in Snake. Oxygen deprivation from near-drowning in water bowls or enclosures. Tissue damage results from external mechanical forces exceeding the structural tolerance of affected tissues. The injury triggers an acute inflammatory cascade with hemorrhage, edema, and pain. Depending on severity, there may be disruption of vascular supply leading to ischemia, contamination with environmental organisms leading to infection, and progressive tissue necrosis. The healing response involves hemostasis, inflammation, proliferation, and remodeling phases.",
        "pathophysiology_ja": "溺水・溺水未遂はSnakeにおける外傷性・機械的疾患である。罹患組織の構造的耐性を超える外部機械的力により組織損傷が生じる。損傷は出血、浮腫、疼痛を伴う急性炎症カスケードを惹起する。重症度に応じて、血管供給の途絶による虚血、環境微生物による汚染、進行性の組織壊死が生じうる。治癒過程は止血、炎症、増殖、リモデリングの各段階を経る。",
        "treatment": "Treatment of drowning / near-drowning in snake prioritizes stabilization, pain management, and wound care. Assess and address life-threatening injuries first (airway, breathing, circulation). Analgesia is essential—use species-appropriate agents (NSAIDs, opioids, local anesthetics). Clean and debride wounds; primary closure, second-intention healing, or reconstructive surgery as indicated. Broad-spectrum antibiotics for contaminated wounds. Splinting or surgical fixation for fractures. Monitor for delayed complications.",
        "treatment_ja": "Snakeにおける溺水・溺水未遂の治療は安定化、疼痛管理、創傷ケアを優先する。生命を脅かす損傷を最初に評価・対処する（気道、呼吸、循環）。種に適した鎮痛薬（NSAIDs、オピオイド、局所麻酔薬）による鎮痛が不可欠である。創傷を洗浄・デブリードマンし、一次閉鎖、二次治癒、再建手術を適宜行う。汚染創には広域抗菌薬を使用する。骨折には副子固定または外科的固定を行う。遅発性合併症をモニタリングする。",
        "prevention": "溺水・溺水未遂の予防には安全で種に適した飼育環境の整備、鋭利物・危険物の除去、適切な取り扱い技術、他の動物との接触時の監視、温度管理、落下防止策が含まれる。",
        "prevention_ja": "溺水・溺水未遂の予防には安全で種に適した飼育環境の整備、鋭利物・危険物の除去、適切な取り扱い技術、他の動物との接触時の監視、温度管理、落下防止策が含まれる。",
        "prognosis": "",
        "prognosis_ja": "溺水・溺水未遂の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"puppy", "young", "adult", "senior"},
    },
    {
        "name": "Aural Abscess (Ear Infection)",
        "name_ja": "耳膿瘍",
        "symptoms": {"anorexia", "head_swelling", "lethargy"},
        "description": "ヘビでは稀だが報告のある中耳膿瘍。",
        "description_ja": "ヘビでは稀だが報告のある中耳膿瘍。",
        "urgency": "moderate",
        "recommended_tests": ["clinical_examination", "radiography", "bacterial_culture"],
        "causes": "Bacterial infection of the middle ear, rare in snakes but reported. May arise from ascending respiratory or oral infections, or hematogenous spread.",
        "causes_ja": "Snakeにおける耳膿瘍の原因: ヘビでは稀だが報告のある中耳膿瘍。",
        "pathophysiology": "耳膿瘍はSnakeにおける細菌感染症である。病原菌は付着因子を通じて組織にコロニーを形成し、毒素産生、酵素分泌、免疫回避戦略などの病原性メカニズムを介して侵入する。好中球浸潤、サイトカイン放出、補体活性化を含む炎症カスケードが生じる。組織損傷は細菌の直接作用と宿主の炎症反応の両方に起因する。菌種と宿主の免疫状態に応じて、膿瘍形成、敗血症、または慢性肉芽腫性炎症が発生しうる。",
        "pathophysiology_ja": "耳膿瘍はSnakeにおける細菌感染症である。病原菌は付着因子を通じて組織にコロニーを形成し、毒素産生、酵素分泌、免疫回避戦略などの病原性メカニズムを介して侵入する。好中球浸潤、サイトカイン放出、補体活性化を含む炎症カスケードが生じる。組織損傷は細菌の直接作用と宿主の炎症反応の両方に起因する。菌種と宿主の免疫状態に応じて、膿瘍形成、敗血症、または慢性肉芽腫性炎症が発生しうる。",
        "treatment": "",
        "treatment_ja": "Snakeにおける耳膿瘍の治療には、可能であれば培養感受性試験に基づく標的抗菌薬療法が必要である。結果待ちの間は経験的広域抗菌薬を開始する。抗菌薬治療期間は感染の排除と耐性予防に十分な期間とする。膿瘍や壊死組織には外科的排膿またはデブリードマンが必要な場合がある。支持療法として輸液、鎮痛薬、抗炎症薬、栄養サポートを行う。",
        "prevention": "溺水・溺水未遂の予防には安全で種に適した飼育環境の整備、鋭利物・危険物の除去、適切な取り扱い技術、他の動物との接触時の監視、温度管理、落下防止策が含まれる。",
        "prevention_ja": "耳膿瘍の予防には適切な衛生管理・消毒、利用可能なワクチン接種、創傷の迅速な処置、ストレス軽減、適切な換気、感染動物の隔離が含まれる。",
        "prognosis": "",
        "prognosis_ja": "耳膿瘍の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"subacute", "chronic"},
        "age_predisposition": {"puppy", "young", "adult", "senior"},
    },
